package it.unimi.dsi.fastutil.objects; public class Object2LongOpenHashMap<K> implements Object2LongMap<K> { final java.util.HashMap<K,Long> m=new java.util.HashMap<>(); long def;
 public void defaultReturnValue(long v){def=v;} public long getLong(Object k){Long v=m.get(k); return v==null?def:v;} public long put(K k,long v){Long o=m.put(k,v); return o==null?def:o;} public long removeLong(Object k){Long o=m.remove(k); return o==null?def:o;}
 public ObjectSet<K> keySet(){ return new ObjectSetImpl<K>(m.keySet()){ public boolean retainAll(java.util.Collection<?> c){ return m.keySet().retainAll(c);} }; } public int size(){return m.size();} public void clear(){m.clear();}
 public ObjectSet<Object2LongMap.Entry<K>> object2LongEntrySet(){ return new ObjectSetImpl<Object2LongMap.Entry<K>>(){ public boolean removeIf(java.util.function.Predicate<? super Object2LongMap.Entry<K>> p){ return m.entrySet().removeIf(e -> p.test(new Object2LongMap.Entry<K>(){ public K getKey(){return e.getKey();} public Long getValue(){return e.getValue();} public long getLongValue(){return e.getValue();} public Long setValue(Long x){throw new UnsupportedOperationException();} })); } }; } }
